update companies set name = 'Lakeshore Catering Co.', category = 'Catering & Events', description = 'Corporate lunches and event catering on the Toronto waterfront.', about = 'Listed by the CanadianSME team from public information. Not yet managed by the owner.', kind = 'storefront', city = 'Toronto', province = 'ON', tz = 'America/Toronto', service_area = '', show_address = true, show_email = false, show_phone = true, show_whatsapp = false, website = 'https://lakeshorecatering.example.ca', booking_url = '', primary_action = 'call', appointments = false, social = '{}'::jsonb, status = 'published', cover_url = 'https://picsum.photos/seed/lakeshore-cover/1200/300', hours = '{"mon": [["08:00", "16:00"]], "tue": [["08:00", "16:00"]], "wed": [["08:00", "16:00"]], "thu": [["08:00", "16:00"]], "fri": [["08:00", "16:00"]], "sat": [], "sun": []}'::jsonb, closures = '[]'::jsonb, claimable = true where slug = 'lakeshore-catering-toronto';
insert into business_private (company_id, street, postal, email, phone, whatsapp) select id, '215 Queens Quay W', 'M5J 2Y3', '', '(416) 555-0199', '' from companies where slug = 'lakeshore-catering-toronto' on conflict (company_id) do update set street = excluded.street, postal = excluded.postal, email = excluded.email, phone = excluded.phone, whatsapp = excluded.whatsapp;
delete from business_services where company_id = (select id from companies where slug = 'lakeshore-catering-toronto');
insert into business_services (company_id, name, description, price_type, price, position) values ((select id from companies where slug = 'lakeshore-catering-toronto'), 'Corporate lunch catering', '', 'quote', null, 0);
delete from business_photos where company_id = (select id from companies where slug = 'lakeshore-catering-toronto');
delete from business_products where company_id = (select id from companies where slug = 'lakeshore-catering-toronto');
delete from business_jobs where company_id = (select id from companies where slug = 'lakeshore-catering-toronto');
